2	
3	const express = require('express');
4	const fs = require('fs');
5	const path = require('path');
6	const os = require('os');
7	const cron = require('node-cron');
8	const backup = require('./backup');
9	const db = require('./db');
10	const agentSync = require('./lib/agentSync');
11	const { loadConfig, saveConfig } = require('./lib/config');
12	
13	const app = express();
14	
15	// ── Middleware ────────────────────────────────────────────────────────────────
16	const corsMiddleware = require('./middleware/cors');
17	const localOnly = require('./middleware/localOnly');
18	const securityHeaders = require('./middleware/security');
19	
20	app.use(corsMiddleware);
21	app.use(localOnly);
22	app.use(securityHeaders);
23	app.use(express.json({ limit: '2mb' }));
24	
25	// Serve built React frontend, fallback to legacy public/
26	const distPath = path.join(__dirname, '..', 'public-dist');
27	const legacyPath = path.join(__dirname, '..', 'public');
28	const staticPath = fs.existsSync(distPath) ? distPath : legacyPath;
29	app.use(express.static(staticPath));
