83	// ── Global error handler ──────────────────────────────────────────────────────
84	app.use((err, req, res, _next) => {
85	  console.error(`[ERROR] ${req.method} ${req.url}:`, err.message);
86	  res.status(err.status || 500).json({
87	    error: process.env.NODE_ENV === 'production' ? 'Internal server error' : err.message,
