99	// ── Start ─────────────────────────────────────────────────────────────────────
100	const PORT = process.env.PORT || 3847;
101	const HOME = os.homedir();
102	const CLAUDE_DIR = path.join(HOME, '.claude');
103	const CONFIG_PATH = path.join(__dirname, '..', 'config.json');
104	
105	app.listen(PORT, () => {
106	  console.log('');
107	  console.log('  ╔══════════════════════════════════════╗');
108	  console.log('  ║          Polyglot is running          ║');
109	  console.log(`  ║     http://localhost:${PORT}            ║`);
110	  console.log('  ╚══════════════════════════════════════╝');
111	  console.log('');
112	  console.log(`  Claude dir: ${CLAUDE_DIR}`);
113	  console.log(`  Config: ${CONFIG_PATH}`);
114	
115	  // Restore scheduled cron jobs
116	  bootSchedules();
117	
118	  // Start backup service (watcher + safety net) if configured
119	  try {
120	    backup.startBackupService();
121	  } catch (err) {
122	    console.log(`  Backup: failed to start — ${err.message}`);
123	  }
124	
125	  // Agent sync: reconcile disk ↔ SQLite registry, then watch for live changes.
126	  try {
127	    const summary = agentSync.reseedFromDisk();
128	    console.log(`  AgentSync: reseeded ${summary.upserted}/${summary.scanned} (${summary.removed} retired, ${summary.errors.length} errors)`);
129	    agentSync.startWatcher();
130	  } catch (err) {
131	    console.log(`  AgentSync: failed to start — ${err.message}`);
132	  }
133	
134	  // Auto-backup SQLite data on startup + every 6 hours
135	  try { db.autoBackupToFile(); } catch {}
136	  setInterval(() => { try { db.autoBackupToFile(); } catch {} }, 6 * 60 * 60 * 1000);
137	
138	  // ── HR cron jobs ──────────────────────────────────────────────────────────
139	  // Roster nightly recompute (02:00 UTC) — refreshes experience profiles
140	  // Witness daily sweep (03:00 UTC) — classifies yesterday's runs
141	  // Cadence weekly review (Monday 09:00 UTC) — applies promotions + PIPs
142	  try {
143	    cron.schedule('0 2 * * *', () => {
144	      try {
145	        const summary = experience.recomputeAllExperience(org);
146	        console.log(`[HR] Roster nightly recompute: ${summary.updated}/${summary.total}`);
147	      } catch (err) {
148	        console.warn(`[HR] Roster recompute failed: ${err.message}`);
149	      }
150	    }, { timezone: 'Etc/UTC' });
151	
152	    cron.schedule('0 3 * * *', () => {
153	      try {
154	        const recent = loadRecentAgentRuns(24);
155	        const result = hr.runWitnessSweep(org, experience, recent);
156	        console.log(`[HR] Witness sweep: ${result.runsClassified} runs, ${result.pipCandidates.length} PIP, ${result.promotionCandidates.length} promo`);
157	      } catch (err) {
158	        console.warn(`[HR] Witness sweep failed: ${err.message}`);
159	      }
160	    }, { timezone: 'Etc/UTC' });
161	
162	    cron.schedule('0 9 * * 1', () => {
163	      try {
164	        const recent = loadRecentAgentRuns(24 * 7);
165	        const review = hr.runCadenceReview(org, experience, recent);
166	        console.log(`[HR] Cadence weekly review ${review.week}: ${review.promotions.length} promotions, ${review.pipsOpened.length} PIPs`);
167	      } catch (err) {
168	        console.warn(`[HR] Cadence review failed: ${err.message}`);
169	      }
170	    }, { timezone: 'Etc/UTC' });
171	
172	    console.log('  HR: cron jobs scheduled (Roster 02:00, Witness 03:00, Cadence Mon 09:00 UTC)');
173	  } catch (err) {
174	    console.warn(`  HR: cron scheduling failed — ${err.message}`);
175	  }
176	
177	  console.log('');
178	});
