3	const rateLimitMap = new Map();
4	const RATE_LIMIT_WINDOW = 60_000; // 1 minute
5	const RATE_LIMITS = {
6	  heavy: 10,   // AI chat, orchestration runs, playground — 10/min
7	  write: 60,   // file writes, creates, deletes — 60/min
8	  read: 200,   // reads, listings — 200/min
9	};
10	
11	function rateLimit(tier) {
12	  const max = RATE_LIMITS[tier] || RATE_LIMITS.read;
13	  return (req, res, next) => {
14	    const key = `${tier}:${req.ip}`;
15	    const now = Date.now();
16	    let entry = rateLimitMap.get(key);
17	    if (!entry || now - entry.start > RATE_LIMIT_WINDOW) {
18	      entry = { start: now, count: 0 };
19	      rateLimitMap.set(key, entry);
20	    }
21	    entry.count++;
22	    if (entry.count > max) {
23	      return res.status(429).json({ error: `Rate limit exceeded (${max}/${RATE_LIMIT_WINDOW / 1000}s)` });
24	    }
25	    next();
26	  };
27	}
28	
29	// Cleanup stale entries every 5 minutes
30	setInterval(() => {
31	  const now = Date.now();
32	  for (const [key, entry] of rateLimitMap) {
33	    if (now - entry.start > RATE_LIMIT_WINDOW * 2) rateLimitMap.delete(key);
34	  }
35	}, 300_000);
36	
37	module.exports = { rateLimit, RATE_LIMITS };
