31	router.get('/dispatch/recommend', (req, res) => {
32	  const q = (req.query.q || '').trim();
33	  if (!q) return res.status(400).json({ error: 'q is required' });
34	
35	  const tokens = tokenize(q);
36	  if (tokens.length === 0) return res.json({ results: [] });
37	
38	  const registry = loadRegistry();
39	  const agents = registry.agents || {};
40	
41	  const scored = [];
42	
43	  for (const [id, agent] of Object.entries(agents)) {
44	    if (agent.status === 'retired') continue;
45	
46	    const skills = agent.skills || {};
47	    let rawScore = 0;
48	    const matchedSkills = [];
49	
50	    for (const token of tokens) {
51	      for (const [skillKey, skillData] of Object.entries(skills)) {
52	        // exact or substring match against skill key
53	        if (skillKey === token || skillKey.includes(token) || token.includes(skillKey)) {
54	          const contribution = (skillData.score || 0) * Math.log1p(skillData.hits || 0);
55	          rawScore += contribution;
56	          if (!matchedSkills.includes(skillKey)) matchedSkills.push(skillKey);
57	        }
58	      }
59	    }
60	
61	    if (rawScore > 0) {
62	      scored.push({
63	        agentId: id,
64	        name: agent.title ? `${id} — ${agent.title}` : id,
65	        department: agent.department || null,
66	        level: agent.levelTitle || null,
67	        tier: agent.tier || null,
68	        status: agent.status || 'active',
69	        score: rawScore,
70	        matchedSkills,
71	      });
72	    }
73	  }
74	
75	  // Normalize scores to 0-1 range
76	  const maxScore = scored.reduce((m, s) => Math.max(m, s.score), 1);
77	  scored.forEach(s => { s.score = Math.round((s.score / maxScore) * 100) / 100; });
78	
79	  scored.sort((a, b) => b.score - a.score);
80	
